"""Author the three previously deferred AC6 identities without adopting them."""
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
import json
from apply_di7_ap_as_01 import G, R, A, info, encoded
from prepare_ac5_current_interfaces_01 import at


def read(p):
    return json.loads(p.read_bytes())


def main():
    output = R / 'data/director/spell_proposals/ac6_planar_completion_draft_01.json'
    checkfile = A / 'AC6_PLANAR_COMPLETION_CHECK_01.json'
    assert not output.exists() and not checkfile.exists()
    audit_path = A / 'AC6_CURRENT_SOURCE_INTERFACE_AUDIT_01.json'
    audit = read(audit_path)
    history_path = R / 'data/director/spell_proposals/abjuration_conjuration_rank6.json'
    history = read(history_path)
    catalog_path = R / 'data/public/spell_playtests/catalog.json'
    index_path = R / 'data/public/spell_playtests/authored_review_index.json'
    catalog, index = read(catalog_path), read(index_path)
    selected = ['planar-barrier', 'planar-ally-greater', 'alignment-nexus']
    cards = {x['id']: x for x in catalog['spells'] if x['id'] in selected}
    entries = {x['id']: x for x in index['entries'] if x['id'] in selected}
    originals = {x['spellId']: x for x in history['completeUntouchedDeferredReceipts']}
    checks = []

    def ck(name, value):
        checks.append({'check': name, 'pass': bool(value)})
        assert value, name

    for ident in selected:
        ck('complete source preserved ' + ident, cards[ident] == originals[ident]['fullSourceAndCurrentAccessRecord'])
        ck('still unadopted ' + ident, entries[ident]['authoredStatus'] == 'pending-authored-procedure')
    ck('ordinary counts unchanged', index['authoredCounts'] == {'reviewed': 435, 'pending': 413})
    source_paths = {G / b['path'] for b in audit['sourceBindings']}
    source_paths.update([audit_path, Path(__file__).resolve()])
    sources = [info(p) for p in sorted(source_paths)]
    for old in audit['sourceBindings']:
        ck('prior preparation source still exact ' + old['path'], info(G / old['path']) == old)

    shared = {
        'status': 'UNADOPTED AND UNSENT. Complete NEW local procedures for actual GPT review; no cosmological identity, spell approval, runtime or balance certification is granted.',
        'casting': 'KEEP each original class access record, repertoire, components, Action and source rank/cost. Planar Barrier and Greater Planar Ally use range60/base13RP; Nexus uses its actually granted Divination6/60/base13 or Conjuration8/120/base21 operation. Apply actual class ability/PB, RP modifiers, strain surcharges, Dissonance/Refrain, casting permissions and interrupt windows. Known illegal choices fail preflight without commitment. Legal casts pay their actual costs and perform any required concentration transition before countering and hidden eligibility; a paid failure gives no refund or revival of the old concentration. A discount changes price, not generating rank.',
        'time': 'NEW maxima use actual elapsed seconds: one minute60, ten minutes600, one hour3600. Expiry resolves first at its exact deadline. Preserve real round, action, resource and event histories through initiative changes, absence, death and planar travel. These spells create no time conversion, beneficial rest, Opening/Horn adjustment or resource refresh.',
        'worldRecords': 'Use actual stable plane/location/body/item identities and established evidence. A mortal map label, creature type, faction, alignment, recent visit or visual resemblance does not establish native origin or identify two planes. Different names do not prove different planes. Unknown/protected fields remain unknown/protected. The procedures below can use genuinely established campaign scene records without naming a universal plane ontology or resolving Heartcell/soul/Old God identities. Synthetic example plane IDs are local hypothetical scene facts, not additions to canon.',
        'alignment': 'Use genuinely defined current effective Law/Chaos and Good/Evil axes, including accepted AP-AS-01 and the scoped AC4-ALIGN-01 Lock/Anchor order. Display masks do not become effective alignment. Nexus snapshots the caster pair at resolution and never ratchets it from later effects; each prospective beneficiary uses their own actual current effective pair at the stated event. Undefined axes cannot be guessed as Neutral. An applicable protection against this actual use of alignment applies in its own scope; a Divination-only protection does not automatically prohibit Conjuration.',
        'transport': 'Only an actually authored transport transaction changes planes. Validate whole bodies, actual separate passengers, custody, geometry and exact prevention predicates. These drafts supply no general teleport path test or global return exception. Accepted BAN-CLOSE-03 remains a narrow ordinary-Banishment mandatory-return exception; it is not inherited by the new summon or portal.',
        'damageAndBodies': 'Use the current body, lifecycle, healing, damage-sharing and Null rules. Original body and item identities survive merely moving or becoming disabled. No new death, loot, harvest, RP or charge trigger is created by administrative ending. At each genuine damage-root creation use its actual dealer; companion damage does not inherit owner Veil merely because it is commanded. Pure transfer retains root flags; genuinely new reflected damage follows its own real source.',
        'control': 'The wall and portal do not issue movement commands or remove ordinary Actions. Actual external forced-movement/control abilities keep their own saves and shared control guard. All of an owner\'s actual companions share the reviewed Bonus Action command and one offensive companion Action per numbered round; two expressly printed attacks can be components of that single Action. Extra turns and replacement create no new allowance.',
        'disclosure': 'No spell reports hidden eligibility, native origin, private alignment, institutional credentials, protected lore or a failed-check diagnosis. Ordinary visible effects can still support ordinary inferences. Source-specific secrecy protection is applied to the actual data and source, not used to erase other unprotected effects.',
    }

    barrier = {
        'activationAndGeometry': 'KEEP Abjuration6, Action,60feet,V/S/F,base13RP and concentration up to60elapsed seconds. NEW choose a fixed vertical rectangular wall up to30feet wide and15feet high, with1foot thickness, resting on actual ground. Choose its full position/orientation before commitment; every point must be within60feet and caster line of effect at formation. Width and height use whole5foot panels, producing at most18panels. No curved dome, moving wall or physical material is supplied. The initial volume must be free of creature bodies and solid terrain; known conflict fails preflight, a hidden conflict discovered at resolution defeats the whole paid formation. The wall is visible but transparent to ordinary sight/sound and does not itself supply cover.',
        'eligibility': 'NEW PB-PRED-01, scoped only to this wall: a creature qualifies if an actual operative source explicitly classifies it as extraplanar, or an actual established native-plane relationship places its native plane elsewhere than the wall\'s plane. A mere current visitor is not assigned a native plane. A record that expressly changes/suppresses that classification is honored for its stated duration. Without either affirmative established basis, this wall imposes no blocking branch; that operational absence is not proof the creature is native or non-extraplanar. Elemental, Fey, Fiend, Humanoid, summoned, outsider and extraplanar are not interchangeable labels. The Director may record a genuinely NEW campaign creature classification explicitly before play, but may not claim it was recovered from cosmology or infer it from a hidden soul theory.',
        'physicalCrossing': 'An operative panel blocks a qualifying creature\'s attempted voluntary or forced physical crossing at its boundary, including that body carried, dragged, grappled or ridden by another. Every separately transported creature retains its own eligibility; hiding a qualifying passenger under a cloak does not turn it into gear. Stop the actual crossing transaction before any qualifying body intersects the panel; no part is severed, squeezed through by changing its name, or left behind without an independently legal release. Movement used to reach the boundary remains spent; impossible remaining movement is not performed. A nonqualifying carrier can release the passenger through its actual available action and move alone if then legal. Nonqualifying bodies, ordinary objects, air, sound and actual attacks pass under their own rules. Going around a real edge remains possible. The wall deals no damage, imposes no extra save and grants no free force or opportunity attack.',
        'fallingAndPlacement': 'NEW selective-wall limitation: it supplies no horizontal support. Unsupported falling continues through its top/bottom and uses the ordinary real Falling history; the wall does not become a one-foot-wide platform or halt a Fall Marker. A lateral forced crossing can stop while the creature continues to fall along its actual remaining vertical trajectory. Actual other terrain/support still matters. The wall does not reserve a berth or eject a body when eligibility changes. If an existing body becomes qualifying while intersecting a panel, that entire5x5panel becomes pending for that wall until no qualifying body intersects it; it supplies no blocking while pending. Once clear it resumes prospectively, with no crushing, relocation, missed action, damage or refreshed duration.',
        'teleportAndTerminalReturn': 'The wall checks an actual transport destination footprint against its operative thickness for qualifying creature bodies; a destination that intersects is barred by this scoped magical endpoint-prevention rule. A fitting destination beyond the wall does not cross a fictitious physical path and is permitted unless another actual rule prevents that transport. An origin alone touching the wall does not bar leaving. Apply each transport source\'s normal atomic failure/payment rule. Ordinary Banishment\'s accepted BAN-CLOSE-03 terminal return expressly overrides endpoint transport prevention: this wall cannot keep that ended cell open. It does not remove real terrain or other bodies. If that mandatory return legally places a qualifying body in the wall thickness, the occupied panel becomes pending under the rule above; no general voluntary-transit bypass is granted.',
        'suppressionAndEnding': 'The wall is a nonphysical ongoing rank6 spell with one parent source and its explicit panels. Local suppression makes intersected panels inactive while its original clock and concentration continue. At resumption, a panel occupied by a qualifying creature remains pending until clear. Entry/resumption is not an attack or a new casting. Losing an underlying ground support invalidates the panels depending on it for the remainder of this cast; it does not move or drop a physical wall. One active Planar Barrier per caster; normal concentration commitment and successful replacement rules apply. Expiry, concentration ending or eligible whole-source dispel ends all panels. No saleable fragments, teleport, planar knowledge or permanent ownership boundary remain.',
    }

