        {'spellId': 'alignment-nexus', 'questionId': 'AC6-14', 'completeSourceAndAccess': cards['alignment-nexus'], 'historicalDeferredReceipt': originals['alignment-nexus'], 'procedure': nexus_common, 'modes': {'Divination6': divination, 'Conjuration8': conjuration}},
